/* mix.js — generated "mix & match" drills. Every drill is built from the words of the chosen lessons
 * (cumulative: the current lesson is weighted, older lessons are interleaved) and only uses grammar the
 * book has introduced by that lesson. All output is generated by js/grammar.js, so it is consistent. */
(() => {
const { U, Store } = App;
const G = window.Grammar;
const pick = (a) => a[Math.floor(Math.random() * a.length)];
const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);
const contract = (s) => s.replace(/\bzu dem\b/g, 'zum').replace(/\bzu der\b/g, 'zur').replace(/\bbei dem\b/g, 'beim').replace(/\bvon dem\b/g, 'vom');

/* ─── word pool ─── */
function pool(lessonIds, focusId) {
  const nouns = [], verbs = [];
  for (const id of lessonIds) {
    const l = DE.lessons[id]; if (!l) continue;
    for (const g of l.vocab) for (const v of g.items) {
      const w = id === focusId ? 3 : 1;
      if (G.declinable(v)) for (let k = 0; k < w; k++) nouns.push({ v, cat: G.category(v, g.group), lesson: id });
      else if (G.isVerb(v)) verbs.push(v);
    }
  }
  return { nouns, verbs };
}
const nounsOf = (P, cats, needPl) => P.nouns.filter((x) => (!cats || cats.includes(x.cat)) && x.v.g !== 'pl' && (!needPl || x.v.pl));
const baseDe = (v) => DE.ART[v.g] + ' ' + v.w;

/* ─── subjects (person index for conjugation) ─── */
const SUBJ = (n) => [['ich', 0], ['du', 1], ['Anna', 2], ['Tom', 2], ['wir', 3], ['ihr', 4], ['Anna und Tom', 5], ['Sie', 5]]
  .concat(n >= 3 ? [['mein Bruder', 2], ['meine Eltern', 5], ['deine Schwester', 2]] : []);
const TIMES = ['heute', 'morgen', 'am Montag', 'am Wochenende', 'am Abend', 'um acht Uhr', 'am Freitag'];
const PAST = ['gestern', 'am Samstag', 'letzte Woche', 'gestern Abend'];

/* ─── verb frames: which verbs take which kind of object, in which case ─── */
const W = G.wordRe;
const DRINK = W('coffee tea water juice beer wine milk cola lemonade cocoa drink');
const INGRED = W('salt sugar oil vinegar flour pepper spice mustard garlic honey jam butter cream quark');
const DISH = W('soup rice pasta noodles potato vegetables egg meat fish chicken roast sauce dish dumpling goulash steak sausage pizza carrot bean pea cabbage mushroom spinach beef pork cake strudel schnitzel salad mash hamburger chips fries pudding gateau quark');
const TEXT = W('e-mail letter message postcard card form list song poem novel application cv invoice bill');
const PUBLIC = W('museum zoo park church exhibition palace castle city town village school university uni concert festival market café cafe restaurant club bar pub cinema theatre opera stadium library gallery cathedral pool lake beach mountain forest gym centre square tower monument inn garden parlour hotel hostel lido island sea river');
const DEST = W('museum zoo park church exhibition palace castle city town village school university uni concert festival market café cafe restaurant club bar pub cinema theatre opera stadium library gallery cathedral pool lake beach mountain forest gym centre square tower monument inn garden parlour hotel hostel lido island sea river station airport bank office supermarket bakery pharmacy hospital practice surgery shop store hall stop platform reception');
const TRANSPORT = W('bus train taxi tram underground metro car bike bicycle plane ship motorbike');
const TOOL = W('computer laptop printer pen pencil phone keyboard mouse program software app tablet camera scissors knife machine dictionary ruler highlighter copier file folder calendar notebook cable charger smartphone');
const NONBUY = W('money cash face hair eye ear nose mouth hand foot leg arm head back belly finger tooth knee neck body floor wall ceiling stairs exit entrance way path street number underground train tram plane ship lift address signature alphabet word sentence name size colour material fabric light heating network internet traffic dialling code continent family tree order subject');
const FRAMES = [
  { v: 'kaufen', cats: ['thing', 'food'], c: 1, art: 'indef', min: 4, not: { test: (e) => INGRED.test(e) || NONBUY.test(e) } }, { v: 'brauchen', cats: ['thing'], c: 1, art: 'indef', min: 4, not: NONBUY },
  { v: 'haben', cats: ['thing'], c: 1, art: 'indef', min: 4, not: NONBUY }, { v: 'suchen', cats: ['thing', 'place', 'person'], c: 1, art: 'def', min: 4 },
  { v: 'sehen', cats: ['thing', 'person', 'place', 'abstract'], c: 1, art: 'def', min: 4, onlyAbs: W('film series fireworks parade rain snow exhibition match game') },
  { v: 'finden', cats: ['thing', 'place', 'abstract'], c: 1, art: 'def', min: 4, tail: ['schön', 'toll', 'praktisch', 'interessant', 'super', 'langweilig'], simple: true },
  { v: 'kennen', cats: ['person', 'place'], c: 1, art: 'def', min: 4, placeOnly: PUBLIC }, { v: 'besuchen', cats: ['person', 'place'], c: 1, art: 'def', min: 4, placeOnly: PUBLIC },
  { v: 'fragen', cats: ['person'], c: 1, art: 'def', min: 4, human: true }, { v: 'nehmen', cats: ['thing', 'food'], c: 1, art: 'def', min: 6, only: { test: (e) => TRANSPORT.test(e) || DISH.test(e) || DRINK.test(e) } },
  { v: 'schreiben', cats: ['thing', 'abstract'], c: 1, art: 'indef', min: 6, only: TEXT },
  { v: 'essen', cats: ['food'], c: 1, art: 'def', min: 9, not: { test: (e) => DRINK.test(e) || INGRED.test(e) } }, { v: 'trinken', cats: ['food'], c: 1, art: 'def', min: 9, only: DRINK },
  { v: 'bestellen', cats: ['food'], c: 1, art: 'indef', min: 9, not: INGRED }, { v: 'kochen', cats: ['food'], c: 1, art: 'def', min: 9, only: DISH }, { v: 'mögen', cats: ['food', 'thing', 'person', 'abstract'], c: 1, art: 'def', min: 9, noModal: true },
  { v: 'einladen', cats: ['person'], c: 1, art: 'def', min: 10, human: true }, { v: 'anrufen', cats: ['person'], c: 1, art: 'def', min: 10, human: true }, { v: 'abholen', cats: ['person'], c: 1, art: 'def', min: 10 },
  { v: 'mitbringen', cats: ['thing', 'food'], c: 1, art: 'indef', min: 10, not: NONBUY }, { v: 'treffen', cats: ['person'], c: 1, art: 'def', min: 7, human: true },
  { v: 'sprechen', cats: ['person'], c: 2, prep: 'mit', art: 'def', min: 4, human: true }, { v: 'telefonieren', cats: ['person'], c: 2, prep: 'mit', art: 'def', min: 6, human: true },
  { v: 'arbeiten', cats: ['thing'], c: 2, prep: 'mit', art: 'def', min: 4, only: TOOL }, { v: 'wohnen', cats: ['person'], c: 2, prep: 'bei', art: 'def', min: 4, human: true },
  { v: 'helfen', cats: ['person'], c: 2, art: 'def', min: 6, human: true }, { v: 'gehen', cats: ['person', 'place'], c: 2, prep: 'zu', art: 'def', min: 8, placeOnly: DEST },
  { v: 'fahren', cats: ['place'], c: 2, prep: 'zu', art: 'def', min: 10, placeOnly: DEST }, { v: 'kommen', cats: ['place'], c: 2, prep: 'aus', art: 'def', min: 10, placeOnly: DEST },
  { v: 'fahren', cats: ['thing'], c: 2, prep: 'mit', art: 'def', min: 10, only: TRANSPORT },
  { v: 'warten', cats: ['person'], c: 1, prep: 'auf', art: 'def', min: 8, human: true },
];
const ANIMAL = W('dog cat horse bird');
const fits = (f, x) => {
  const en = G.head(x.v);
  if (f.only && !f.only.test(en)) return false;
  if (f.not && f.not.test(en)) return false;
  if (f.human && ANIMAL.test(en)) return false;
  if (x.cat === 'place' && f.placeOnly && !f.placeOnly.test(en)) return false;
  if (x.cat === 'abstract' && f.onlyAbs && !f.onlyAbs.test(en)) return false;
  return true;
};

/* builds one sentence: returns { tokens, text, prompt } */
function sentence(P, n, forceMode) {
  const frames = FRAMES.filter((f) => f.min <= n);
  for (let tries = 0; tries < 40; tries++) {
    const f = pick(frames);
    const cand = nounsOf(P, f.cats).filter((x) => fits(f, x));
    if (!cand.length) continue;
    const { v } = pick(cand);
    const T = G.table(v);
    const pl = v.pl && Math.random() < 0.3;
    let art = f.art;
    if (pl && art === 'indef') art = 'def';
    if (v.pl === '' && art === 'indef') art = 'def';
    const modes = ['plain'];
    if (n >= 3) modes.push('question');
    if (n >= 5 && art === 'indef' && f.c === 1 && !f.prep) modes.push('kein');
    if (n >= 7 && !f.noModal && !f.simple) modes.push('modal');
    if (n >= 8) modes.push('time', 'time');
    if (n >= 11 && !f.simple && (G.conjugate(f.v).aux === 'haben' || n >= 12)) modes.push('perfekt', 'perfekt');
    const mode = forceMode && modes.includes(forceMode) ? forceMode : pick(modes);
    const objArt = mode === 'kein' ? 'neg' : art;
    let obj = (objArt === 'indef' && pl) ? T.indef.pl[f.c] : T[objArt][pl ? 'pl' : 'sg'][f.c];
    if (!obj) continue;
    if (f.prep) obj = contract(f.prep + ' ' + obj);
    const tail = f.tail ? pick(f.tail) : '';
    const [subj, pi] = pick(SUBJ(n));
    const c = G.conjugate(f.v);
    const verbParts = (form) => form.split(' '); // [finite, prefix?]
    let tokens, label;
    const objT = obj.split(' ').concat(tail ? [tail] : []);
    const objBase = (f.prep ? f.prep + ' ' : '') + (objArt === 'neg' ? 'kein-' : objArt === 'indef' ? (pl ? '' : (v.g === 'f' ? 'eine ' : 'ein ')) : (pl ? 'die ' : DE.ART[v.g] + ' ')) + (pl ? v.pl : v.w);
    if (mode === 'modal') {
      const modal = n >= 9 && Math.random() < 0.5 ? 'möchten' : 'können';
      const m = G.conjugate(modal).pres[pi];
      tokens = [subj, m, ...objT, c.inf];
      label = `+ ${modal}`;
    } else if (mode === 'perfekt') {
      const aux = G.AUX[c.aux === 'sein' ? 'sein' : 'haben'][pi];
      const t = pick(PAST);
      tokens = [cap(t), aux, subj, ...objT, c.part];
      label = `Perfekt · start with „${cap(t)}"`;
    } else {
      const [fin, pre] = verbParts(c.pres[pi]);
      if (mode === 'question') { tokens = [cap(fin), subj, ...objT, ...(pre ? [pre] : [])]; label = 'Ja/Nein-Frage'; }
      else if (mode === 'time') { const t = pick(TIMES); tokens = [cap(t), fin, subj, ...objT, ...(pre ? [pre] : [])]; label = `start with „${cap(t)}"`; }
      else { tokens = [subj, fin, ...objT, ...(pre ? [pre] : [])]; label = mode === 'kein' ? 'verneinen mit kein-' : 'Aussage'; }
    }
    tokens[0] = cap(tokens[0]);
    const end = mode === 'question' ? '?' : '.';
    const text = tokens.join(' ').replace(/\bSie\b/g, (m, i) => m) + end;
    const prompt = `${subj} · ${f.v}${c.sep ? ' (trennbar)' : ''} · ${objBase}${tail ? ' · ' + tail : ''} → ${label}`;
    return { tokens: tokens.concat([end]), text, prompt, mode };
  }
  return null;
}

/* ─── generators ─── each returns an exercise object for App.Exercises.render */
const GEN = {
  genus: { title: 'Genus: der, das oder die?', min: 1, make(P) {
    const items = U.shuffle(nounsOf(P)).filter((x, i, a) => a.findIndex((y) => y.v.w === x.v.w) === i).slice(0, 12).map((x) => [x.v.w, DE.ART[x.v.g]]);
    return items.length >= 4 && { type: 'sort', buckets: ['der', 'das', 'die'], items };
  } },
  plural: { title: 'Plural: Wie heißt der Plural?', min: 3, make(P) {
    const items = U.shuffle(nounsOf(P, null, true)).slice(0, 10).map((x) => `${baseDe(x.v)} → die {${x.v.pl}}`);
    return items.length >= 4 && { type: 'gap', items: [...new Set(items)] };
  } },
  pronomen: { title: 'Pronomen: er, es oder sie?', min: 4, make(P) {
    const items = U.shuffle(nounsOf(P, ['thing', 'place', 'food', 'abstract'])).slice(0, 8).map((x) => {
      const pl = x.v.pl && Math.random() < 0.3;
      return pl ? `Wo sind die ${x.v.pl}? – {Sie} sind hier.` : `Wo ist ${baseDe(x.v)}? – {${{ m: 'Er', n: 'Es', f: 'Sie' }[x.v.g]}} ist hier.`;
    });
    return items.length >= 4 && { type: 'gap', items: [...new Set(items)] };
  } },
  einkein: { title: 'ein / eine → kein / keine', min: 5, make(P) {
    const items = U.shuffle(nounsOf(P, ['thing', 'food'])).filter((x) => x.v.pl !== '').slice(0, 8).map((x) => {
      const t = G.table(x.v), akk = Math.random() < 0.5;
      return akk ? `Ich habe ${t.indef.sg[1]}. → Ich habe {${t.neg.sg[1]}}.` : `Das ist ${t.indef.sg[0]}. → Das ist {${t.neg.sg[0]}}.`;
    });
    return items.length >= 4 && { type: 'gap', items: [...new Set(items)] };
  } },
  nichtkein: { title: 'nicht oder kein?', min: 5, make(P) {
    const xs = U.shuffle(nounsOf(P, ['thing', 'food']).filter((x) => x.v.pl !== '')).slice(0, 9);
    const items = xs.map((x, i) => {
      const t = G.table(x.v), k = t.neg.sg[0].split(' ')[0];
      if (i % 3 === 0) return { q: `Das ist ___ ${G.ART.poss[x.v.g][0]} ${x.v.w}.`, options: ['nicht', 'kein', 'keine'], a: 0, explain: 'mein/dein/der … → nicht' };
      if (i % 3 === 1) return { q: `${cap(t.def.sg[0])} ist ___ teuer.`, options: ['nicht', 'kein', 'keine'], a: 0, explain: 'adjective → nicht' };
      return { q: `Das ist ___ ${x.v.w}. (≠ ${t.indef.sg[0]})`, options: ['nicht', 'kein', 'keine'], a: k === 'kein' ? 1 : 2, explain: `${t.indef.sg[0]} → ${t.neg.sg[0]}` };
    });
    return items.length >= 4 && { type: 'mc', items };
  } },
  possessiv: { title: 'Possessivartikel mein / dein', min: 3, make(P, n) {
    const items = U.shuffle(nounsOf(P)).slice(0, 8).map((x) => {
      const t = G.ART.poss[x.v.g]; const who = Math.random() < 0.5 ? ['mein', 'my'] : ['dein', 'your'];
      const fix = (a) => a.replace(/^mein/, who[0]);
      if (n >= 6 && Math.random() < 0.5) return `Ich suche {${fix(t[1])}} ${x.v.w}. (${who[1]} · Akkusativ)`;
      if (n >= 6 && Math.random() < 0.3) return `Ich komme mit {${fix(t[2])}} ${x.v.w}. (${who[1]} · Dativ)`;
      return `Das ist {${fix(t[0])}} ${x.v.w}. (${who[1]})`;
    });
    return items.length >= 4 && { type: 'gap', items: [...new Set(items)] };
  } },
  artikel: { title: 'Artikel im Kasus: Welcher Artikel passt?', min: 4, make(P, n) {
    const xs = U.shuffle(nounsOf(P)).slice(0, 8);
    const items = xs.map((x) => {
      const fr = U.shuffle(G.frames[x.cat].filter(([ci, num]) => num === 'sg' && (n >= 6 || ci === 0 || ci === 2)))[0]; if (!fr) return null;
      const [ci, , tpl] = fr; const art = G.ART.def[x.v.g][ci];
      const opts = ['der', 'die', 'das', 'den', 'dem', 'des'];
      const t = G.table(x.v);
      const q = tpl.replace('{X}', '___ ' + t.forms.sg[ci]);
      return { q: cap(q) + ` (${G.CASES[ci]})`, options: opts, a: opts.indexOf(art), explain: `${G.CASES[ci]}: ${t.def.sg[ci]}` };
    }).filter(Boolean);
    return items.length >= 4 && { type: 'mc', items };
  } },
  kasus: { title: 'Kasus-Training: Artikel + Nomen', min: 4, make(P, n, l) { return App.Forms.kasusDrill({ vocab: [{ group: '', items: [...new Set(P.nouns.map((x) => x.v))] }], n }, 10); } },
  konj: { title: 'Konjugation', min: 1, make(P, n) {
    const verbs = P.verbs.filter((v) => !/^sich /.test(v.w)); if (!verbs.length) return null;
    return App.Forms.konjDrill({ vocab: [{ group: '', items: verbs }], n }, 10);
  } },
  partizip: { title: 'Partizip II + haben/sein', min: 11, make(P) {
    const verbs = U.shuffle(P.verbs.filter((v) => !/^sich /.test(v.w))).slice(0, 10);
    const items = verbs.map((v) => { const c = G.conjugate(v.w); return `${c.inf} → er {${c.aux === 'sein' ? 'ist' : 'hat'}} … {${c.part}}`; });
    return items.length >= 4 && { type: 'gap', items: [...new Set(items)] };
  } },
  hilfsverb: { title: 'Perfekt: haben oder sein?', min: 12, make(P) {
    const vs = U.shuffle(P.verbs.filter((v) => !/^sich /.test(v.w)));
    const sein = vs.filter((v) => G.conjugate(v.w).aux === 'sein').slice(0, 5), haben = vs.filter((v) => G.conjugate(v.w).aux === 'haben').slice(0, 5);
    const items = U.shuffle(sein.concat(haben)).map((v) => { const c = G.conjugate(v.w); return { q: `Wir ___ ${c.part}. (${c.inf})`, options: ['haben', 'sind'], a: c.aux === 'sein' ? 1 : 0 }; });
    return items.length >= 4 && { type: 'mc', items };
  } },
  satzbau: { title: 'Satzbaukasten: Wörter in die richtige Reihenfolge', min: 4, make(P, n) {
    const items = []; for (let i = 0; i < 12 && items.length < 6; i++) { const s = sentence(P, n); if (s && !items.find((x) => x.words.join(' ') === s.tokens.join(' '))) items.push({ words: s.tokens, en: s.prompt }); }
    return items.length >= 3 && { type: 'order', items };
  } },
  satz: { title: 'Sätze bilden: Schreiben Sie den ganzen Satz', min: 4, make(P, n) {
    const items = []; for (let i = 0; i < 14 && items.length < 6; i++) { const s = sentence(P, n); if (s && !items.find((x) => x.a === s.text)) items.push({ prompt: s.prompt, a: s.text }); }
    return items.length >= 3 && { type: 'build', items };
  } },
};
App.Mix = {
  GEN,
  unlocked: (n) => Object.entries(GEN).filter(([, g]) => g.min <= n).map(([k]) => k),
  pool,
  /* make one exercise of a given kind for lessons up to focus */
  make(kind, lessonIds, focusId) {
    const g = GEN[kind]; const P = pool(lessonIds, focusId);
    const n = Math.max(...lessonIds.map((id) => DE.lessons[id].n));
    const ex = g.make(P, Math.floor(n + 0.01), DE.lessons[focusId]);
    if (!ex) return null;
    ex.title = g.title + (lessonIds.length > 1 ? ` · Mix ${lessonIds[0]}–${lessonIds[lessonIds.length - 1]}` : '');
    ex.mix = kind;
    return ex;
  },
  /* adaptive pick: weaker kinds come up more often */
  weights(kinds) {
    const st = (Store.data.mixStats = Store.data.mixStats || {});
    return kinds.map((k) => { const s = st[k]; const acc = s && s.n ? s.ok / s.n : 0.5; return { k, w: 0.3 + (1 - acc) * 1.5 + (s ? 0 : 0.5) }; });
  },
  record(kind, pct) { const st = (Store.data.mixStats = Store.data.mixStats || {}); const s = (st[kind] = st[kind] || { n: 0, ok: 0 }); s.n += 1; s.ok += pct; Store.save(); },
  sentence,
};
})();
